-- CR-002 보완 2 (2026-10-08) — GPT 리뷰 반영
-- [높음 #2] 음력 생년월일의 양력 변환값을 브라우저가 조작해 만 14세 검사를 우회할 수 있음
--   → DB가 음력→양력을 직접 계산해 solar_birth_date를 덮어쓴다. 표는 manseryeok 2.0.0(KASI 데이터, MIT)에서 생성(1900~2030),
--     각 달 시작일이 앞 달 시작일+일수와 이어지는지 생성 시 검증함.
create table private.lunar_years (
  year smallint primary key,
  new_year_solar date not null,
  leap_month smallint not null check (leap_month between 0 and 12),
  -- 달 순서대로(윤달은 해당 달 바로 뒤) 일수 '29'/'30'을 이어 붙인 문자열
  month_days text not null check (month_days ~ '^(29|30){12,13}$')
);
revoke all on private.lunar_years from public, anon, authenticated;


create function private.lunar_to_solar(p_year int, p_month int, p_day int, p_leap boolean)
returns date language plpgsql stable set search_path = ''
as $$
declare
  r private.lunar_years;
  idx int := 0;      -- 목표 달의 순서(0부터)
  offset_days int := 0;
  len int;
  i int;
begin
  select * into r from private.lunar_years where year = p_year;
  if not found then return null; end if;
  if p_leap and r.leap_month <> p_month then return null; end if;
  -- 목표 달의 순서: 1월=0 … 윤달은 해당 달 바로 뒤
  idx := p_month - 1;
  if r.leap_month > 0 and (p_month > r.leap_month or (p_month = r.leap_month and p_leap)) then idx := idx + 1; end if;
  for i in 0 .. idx - 1 loop
    offset_days := offset_days + substr(r.month_days, i * 2 + 1, 2)::int;
  end loop;
  len := substr(r.month_days, idx * 2 + 1, 2)::int;
  if p_day < 1 or p_day > len then return null; end if;
  return r.new_year_solar + offset_days + (p_day - 1);
end;
$$;
revoke execute on function private.lunar_to_solar(int, int, int, boolean) from public, anon, authenticated;

-- 이름순으로 profiles_age보다 먼저 실행되도록 '0_' 접두어
-- security definer: 사용자 권한으로는 private.lunar_years·lunar_to_solar에 접근할 수 없으므로 소유자 권한으로 실행
create function private.set_solar_birth_date()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare
  v date;
begin
  if new.calendar = 'lunar' then
    v := private.lunar_to_solar(new.birth_year, new.birth_month, new.birth_day, new.is_leap_month);
  else
    begin
      v := make_date(new.birth_year, new.birth_month, new.birth_day);
    exception when others then
      v := null;
    end;
  end if;
  if v is null then raise exception 'invalid_birth_date' using errcode = '23514'; end if;
  new.solar_birth_date := v; -- 브라우저가 보낸 값은 쓰지 않는다
  return new;
end;
$$;
revoke execute on function private.set_solar_birth_date() from public, anon, authenticated;
create trigger profiles_0_solar_date before insert or update on public.profiles
  for each row execute function private.set_solar_birth_date();
